ALTER TABLE public.tg_users ADD COLUMN IF NOT EXISTS captcha_verified boolean NOT NULL DEFAULT false;
CREATE OR REPLACE FUNCTION public.tg_move_points(p_tg_id bigint, p_delta integer, p_kind text, p_note text DEFAULT '') RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ BEGIN UPDATE public.tg_users SET points = points + p_delta, points_earned = points_earned + greatest(p_delta,0), points_spent = points_spent + greatest(-p_delta,0) WHERE tg_id = p_tg_id AND points + p_delta >= 0; IF NOT FOUND THEN RETURN false; END IF; INSERT INTO public.tg_txn(tg_id,kind,amount,note) VALUES(p_tg_id,p_kind,p_delta,p_note); RETURN true; END; $$;
REVOKE ALL ON FUNCTION public.tg_move_points(bigint,integer,text,text) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.tg_move_points(bigint,integer,text,text) TO service_role;
CREATE OR REPLACE FUNCTION public.tg_claim_reward(p_tg_id bigint, p_day date, p_kind text, p_points integer, p_streak integer DEFAULT 0) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ BEGIN IF p_points < 0 THEN RAISE EXCEPTION 'Invalid reward'; END IF; IF p_kind = 'daily_box' THEN UPDATE public.tg_users SET last_box_at=p_day,last_checkin=p_day,streak=p_streak WHERE tg_id=p_tg_id AND (last_box_at IS NULL OR last_box_at < p_day); ELSIF p_kind='spin' THEN UPDATE public.tg_users SET last_spin_at=p_day WHERE tg_id=p_tg_id AND (last_spin_at IS NULL OR last_spin_at < p_day); ELSE RAISE EXCEPTION 'Invalid reward kind'; END IF; IF NOT FOUND THEN RETURN false; END IF; RETURN public.tg_move_points(p_tg_id,p_points,p_kind,'Daily reward'); END; $$;
REVOKE ALL ON FUNCTION public.tg_claim_reward(bigint,date,text,integer,integer) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.tg_claim_reward(bigint,date,text,integer,integer) TO service_role;
CREATE OR REPLACE FUNCTION public.tg_exchange_code(p_tg_id bigint,p_days integer) RETURNS text LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE u public.tg_users%ROWTYPE; s public.app_settings%ROWTYPE; c text; cost integer; BEGIN SELECT * INTO u FROM public.tg_users WHERE tg_id=p_tg_id FOR UPDATE; SELECT * INTO s FROM public.app_settings WHERE id=1; IF u.tg_id IS NULL OR u.banned OR u.profile_id IS NULL OR p_days < 1 OR p_days > 365 THEN RAISE EXCEPTION 'Cannot exchange'; END IF; cost := p_days * greatest(s.tg_points_per_day,1); IF u.points < cost THEN RAISE EXCEPTION 'Insufficient points'; END IF; c := 'WORM-' || upper(substr(replace(gen_random_uuid()::text,'-',''),1,12)); INSERT INTO public.gift_codes(code,plan,days,max_uses) VALUES(c,CASE WHEN s.tg_trial_plan IN ('plus','pro','ultra') THEN s.tg_trial_plan ELSE 'plus' END,p_days,1); PERFORM public.tg_move_points(p_tg_id,-cost,'exchange',p_days::text || ' days'); RETURN c; END; $$;
REVOKE ALL ON FUNCTION public.tg_exchange_code(bigint,integer) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.tg_exchange_code(bigint,integer) TO service_role;